      margin-top: var(--space-7);
    }

    .showcase-card {
      position: relative;
      display: flex;
      min-height: 260px;
      overflow: hidden;
      flex-direction: column;
      justify-content: space-between;
      padding: clamp(24px, 4vw, 42px);
      border-radius: var(--radius-md);
      background: var(--color-cream);
    }

    .showcase-card--red {
      background: var(--color-red);
      color: var(--color-white);
    }

    .showcase-card--dark {
      background: var(--color-ink);
      color: var(--color-white);
    }

    .showcase-card__shape {
      position: absolute;
      right: -50px;
      bottom: -90px;
      width: 240px;
      height: 240px;
      border: 25px solid rgb(32 28 26 / 9%);
      border-radius: 50%;
    }

    .showcase-card--red .showcase-card__shape {
      border-color: rgb(255 255 255 / 14%);
    }

    .showcase-card--dark .showcase-card__shape {
      border-color: rgb(255 243 223 / 12%);
    }

    .showcase-card__label {
      position: relative;
      z-index: 1;
      font-size: 0.7rem;
      font-weight: 800;
      letter-spacing: 0.15em;
      text-transform: uppercase;
    }

    .showcase-card__title {
      position: relative;
      z-index: 1;
      max-width: 470px;
      margin: 35px 0 0;
      font-family: var(--font-display);
      font-size: clamp(2rem, 4.6vw, 4.1rem);
      letter-spacing: -0.06em;
      line-height: 0.98;
      text-transform: uppercase;
    }

    .showcase__footnote {
      margin-top: 16px;
      color: var(--color-muted);
      font-size: 0.76rem;
    }

    /* =========================================================
       SECTIONS: Reviews
    ========================================================= */
    .reviews {
      padding-block: var(--space-9);
      background: var(--color-cream);
    }

    .reviews__grid {
      display: grid;
      align-items: center;
      gap: 50px;
      grid-template-columns: 0.8fr 1.2fr;
    }

    .reviews__score {
      margin: 20px 0 0;
      font-family: var(--font-display);
      font-size: clamp(4.5rem, 10vw, 7.5rem);
      letter-spacing: -0.08em;
      line-height: 1;
    }

    .reviews__stars {
      margin-top: 8px;
      color: #9c6100;
      font-size: 1.3rem;
      letter-spacing: 0.1em;
    }

    .reviews__meta {
      color: var(--color-muted);
      font-size: 0.85rem;
    }

    .reviews__quote {
      margin: 0;
      padding: clamp(25px, 5vw, 48px);
      border: 1px solid var(--color-line);
      border-radius: var(--radius-md);
      background: var(--color-paper);
    }

    .reviews__quote-mark {
      color: var(--color-red);
      font-family: Georgia, serif;
      font-size: 4rem;
      line-height: 0.8;
    }

    .reviews__quote-text {
      margin: 20px 0;
      font-family: var(--font-display);
      font-size: clamp(1.3rem, 2.5vw, 2rem);
      letter-spacing: -0.04em;
      line-height: 1.25;
    }

    .reviews__quote-source {
      margin-bottom: 20px;
      color: var(--color-muted);
      font-size: 0.8rem;
    }

    /* =========================================================
       SECTIONS: Location
    ========================================================= */
    .location {
      padding-block: var(--space-10);
    }

    .location__grid {
      display: grid;
      gap: 50px;
      grid-template-columns: 1fr 1fr;
    }

    .location__details {
      display: grid;
      gap: 0;
      margin-top: 28px;
    }

    .location__row {
      display: grid;
      gap: 12px;
      grid-template-columns: 34px 1fr;
      padding-block: 18px;
      border-bottom: 1px solid var(--color-line);
    }

    .location__icon {
      color: var(--color-red);
    }

    .location__icon svg {
      width: 23px;
      height: 23px;
    }

    .location__label {
      display: block;
      margin-bottom: 3px;
      color: var(--color-muted);
      font-size: 0.72rem;
      font-weight: 700;
      text-transform: uppercase;
    }

    .location__value {
      font-size: 0.94rem;
      font-weight: 700;
    }

    .location__hours {
      display: grid;
      gap: 5px;
      margin-top: 8px;
      color: var(--color-muted);
      font-size: 0.8rem;
    }

    .location__hours-row {
      display: flex;
      justify-content: space-between;
      gap: 12px;
    }

    .location__hours-row.is-today {
      color: var(--color-ink);
      font-weight: 800;
    }

    .location__map {
      position: relative;
      display: flex;
      min-height: 420px;
      flex-direction: column;
      justify-content: space-between;
      overflow: hidden;
      padding: 30px;
      border-radius: var(--radius-lg);
      background-color: #eae0ce;
      background-image:
        linear-gradient(25deg, transparent 48%, #d1c4ac 49%, #d1c4ac 51%, transparent 52%),
        linear-gradient(115deg, transparent 45%, #f9f0df 46%, #f9f0df 53%, transparent 54%),
        linear-gradient(165deg, transparent 60%, #d6c9b1 61%, #d6c9b1 63%, transparent 64%);
      background-size: 180px 150px, 220px 180px, 200px 220px;
    }

    .location__map::before {
      position: absolute;
      top: 0;
      right: 0;
      bottom: 0;
      left: 0;
      background: repeating-linear-gradient(
        45deg,
        transparent 0 40px,
        rgb(255 255 255 / 24%) 41px 44px,
        transparent 45px 80px
      );
      content: "";
    }

    .location__map-label {
      position: relative;
      z-index: 1;
      align-self: flex-start;
      padding: 8px 12px;
      border-radius: var(--radius-pill);
      background: var(--color-white);
      font-size: 0.72rem;
      font-weight: 800;
    }

    .location__pin {
      position: absolute;
      top: 43%;
      left: 50%;
      z-index: 1;
      display: grid;
      width: 72px;
      height: 72px;
      place-items: center;
      border: 7px solid rgb(255 255 255 / 80%);
      border-radius: 50%;
      background: var(--color-red);
      color: var(--color-white);
      box-shadow: 0 10px 30px rgb(32 28 26 / 20%);
      transform: translate(-50%, -50%) rotate(-8deg);
    }

    .location__pin svg {
      width: 29px;
      height: 29px;
    }

    .location__map-card {
      position: relative;
      z-index: 1;
      padding: 20px;
      border-radius: var(--radius-md);
      background: var(--color-white);
      box-shadow: var(--shadow-card);
    }

    .location__map-card strong {
      display: block;
      font-family: var(--font-display);
      font-size: 1.1rem;
      text-transform: uppercase;
    }

    .location__map-card p {
      margin: 5px 0 15px;
      color: var(--color-muted);
      font-size: 0.8rem;
    }

    /* =========================================================
       SECTIONS: Final CTA and footer
    ========================================================= */
    .final-cta {
      overflow: hidden;
      padding-block: var(--space-9);
      background: var(--color-red);
      color: var(--color-white);
    }

    .final-cta__inner {
      position: relative;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 40px;
    }

    .final-cta__copy {
      position: relative;
      z-index: 1;
      max-width: 750px;
    }

    .final-cta .eyebrow::before {
      background: var(--color-gold);
    }

    .final-cta__title {
      font-size: clamp(3rem, 7vw, 6.5rem);
    }

    .final-cta__text {
      max-width: 480px;
      color: #ffe2d8;
    }

    .final-cta__button {
      position: relative;
      z-index: 1;
      flex-shrink: 0;
    }

    .footer {
      padding-block: 35px;
      background: var(--color-ink);
      color: var(--color-white);
    }

    .footer__top {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 30px;
      padding-bottom: 28px;
      border-bottom: 1px solid rgb(255 255 255 / 15%);
    }

    .footer .brand__sub {
      color: #c8bfb5;
    }

    .footer__links {
      display: flex;
      flex-wrap: wrap;
      gap: 22px;
    }

    .footer__link {
      color: #e2d8cc;
      font-size: 0.8rem;
      font-weight: 600;
    }

    .footer__link:hover {
      color: var(--color-gold);
    }

    .footer__bottom {
      display: flex;
      justify-content: space-between;
      gap: 20px;
      padding-top: 20px;
      color: #c8bfb5;
      font-size: 0.73rem;
    }

    /* =========================================================
       MOTION
    ========================================================= */
    [data-reveal] {
      opacity: 1;
      transform: none;
    }

    .motion-ready [data-reveal] {
      opacity: 0;
      transform: translateY(18px);
      transition:
        opacity 650ms var(--ease-out),
        transform 650ms var(--ease-out);
    }

    .motion-ready [data-reveal].is-visible {
      opacity: 1;
      transform: translateY(0);
    }

    .motion-ready .hero__content [data-reveal] {
      transition-delay: 100ms;
    }

    .motion-ready .menu-card[data-reveal]:nth-child(2) {
      transition-delay: 80ms;
    }

    .motion-ready .menu-card[data-reveal]:nth-child(3) {
      transition-delay: 160ms;
    }

    /* =========================================================
       RESPONSIVE
    ========================================================= */
    @media (min-width: 1600px) {
      .hero__title {
        font-size: 8rem;
      }

      .hero-art {
        max-width: 650px;
        justify-self: end;
      }
    }

    @media (max-width: 900px) {
      .nav__links {
        gap: 16px;
      }

      .nav__links .nav__link {
        display: none;
      }

      .hero__grid {
        grid-template-columns: 1fr 0.85fr;
        gap: 25px;
      }

      .hero__title {
        font-size: clamp(3.3rem, 8vw, 5.5rem);
      }

      .hero-art {
        min-height: 330px;
      }

      .hero-art__sticker {
        width: 90px;
        font-size: 0.68rem;
      }

      .menu__grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }

      .story__grid {
        gap: 35px;
      }

      .location__grid {
        gap: 30px;
      }

      .location__map {
        min-height: 370px;
      }

      .final-cta__inner {
        align-items: flex-start;
        flex-direction: column;
      }
    }

    @media (max-width: 600px) {
      .container {
        width: min(calc(100% - 32px), var(--content-width));
      }

      .nav {
        min-height: 72px;
      }

      .brand__mark {
        width: 39px;
        height: 39px;
      }

      .brand__name {
        font-size: 0.91rem;
      }

      .nav__cta {
        min-height: 42px;
        padding: 9px 14px;
      }

      .hero {
        padding-block: 50px 35px;
      }

      .hero__grid {
        grid-template-columns: 1fr;
        gap: 12px;
      }

      .hero__title {
        font-size: clamp(3.4rem, 14vw, 5.5rem);
      }

      .hero__description {
        margin-block: 22px;
      }

      .hero__actions {
        display: grid;
        grid-template-columns: 1fr;
      }

      .hero__actions .button {
        width: 100%;
      }

      .hero-art {
        width: min(100%, 390px);
        min-height: 0;
        margin: 0 auto;
      }

      .hero-art__sticker--top {
        right: 2%;
      }

      .hero-art__sticker--bottom {
        left: 1%;
      }

      .trust {
        padding-block: 20px;
      }

      .trust__grid {
        grid-template-columns: 1fr;
        gap: 17px;
      }

      .trust__item {
        justify-content: flex-start;
        text-align: left;
      }

      .menu,
      .showcase,
      .location {
        padding-block: 65px;
      }

      .section-top {
        align-items: flex-start;
        flex-direction: column;
        gap: 16px;
        margin-bottom: 28px;
      }

      .section-top > .button {
        width: 100%;
      }

      .section-heading {
        font-size: clamp(2.6rem, 12vw, 4rem);
      }

      .menu__grid {
        grid-template-columns: 1fr;
        gap: 14px;
      }

      .menu-card {
        min-height: 315px;
        padding: 23px;
      }

      .story {
        padding-block: 55px;
      }

      .story__grid {
        grid-template-columns: 1fr;
        gap: 35px;
      }

      .story__graphic {
        min-height: 300px;
      }

      .showcase__grid {
        grid-template-columns: 1fr;
        gap: 14px;
        margin-top: 28px;
      }

      .showcase-card {
        min-height: 250px;
      }

      .reviews {
        padding-block: 60px;
      }

      .reviews__grid {
        grid-template-columns: 1fr;
        gap: 25px;
      }

      .reviews__score {
        font-size: 5.5rem;
      }

      .location__grid {
        grid-template-columns: 1fr;
      }

      .location__map {
        min-height: 340px;
      }

      .final-cta {
        padding-block: 60px;
      }

      .final-cta__title {
        font-size: clamp(3rem, 13vw, 4.8rem);
      }

      .final-cta__button {
        width: 100%;
      }

      .footer__top,
      .footer__bottom {
        align-items: flex-start;
        flex-direction: column;
      }

      .footer__links {
        gap: 15px 20px;
      }
    }

    @media (max-width: 360px) {
      .container {
        width: calc(100% - 28px);
      }

      .hero__title {
        font-size: 3.1rem;
      }

      .brand__sub {
        font-size: 0.57rem;
      }

      .nav__cta {
        padding-inline: 11px;
        font-size: 0.73rem;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
      }

      .motion-ready [data-reveal] {
        opacity: 1;
        transform: none;
      }
    }
